const $=s=>document.querySelector(s),money=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(n),num=n=>new Intl.NumberFormat('en-US').format(n),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let data=null,page='overview',plan=null,acdiData=null,suppliersData=null,timingData=null,validateData=null,demoData=null,activeSupTab='BKK',oppFilter={destination:'all',category:'all'};
const pages={overview:'Overview',history:'Historical intelligence',social:'Social trend radar',market:'Market intelligence',forecast:'Demand forecasting',opportunities:'Opportunity explorer',planner:'Procurement planner',risk:'Risk simulator',recommendations:'Recommendation center','hidden-demand':'Hidden demand intelligence',suppliers:'Supplier intelligence',demo:'Demo — Bangkok Songkran'};
async function api(url,options){const r=await fetch(url,options);const j=await r.json();if(!r.ok)throw Error(j.error||'Could not load data');return j}
function toast(s){const e=$('#toast');e.textContent=s;e.classList.add('show');setTimeout(()=>e.classList.remove('show'),2600)}
function chartSvg(rows){const W=720,H=195,L=36,R=12,T=10,B=25,vals=rows.map(r=>r.bookings),max=Math.ceil(Math.max(...vals)*1.25/250)*250,min=Math.floor(Math.min(...vals)*.72/250)*250,x=i=>L+i*(W-L-R)/(rows.length-1),y=v=>T+(max-v)*(H-T-B)/(max-min),future=rows.map((r,i)=>Math.round(r.bookings*(1+.055+i*.006)));let path=vals.map((v,i)=>`${i?'L':'M'}${x(i)} ${y(v)}`).join(' '),fpath=future.map((v,i)=>`${i?'L':'M'}${x(i)} ${y(v)}`).join(' ');return `<svg viewBox="0 0 ${W} ${H}" role="img" aria-label="Monthly bookings"><defs><linearGradient id="area" x1="0" x2="0" y1="0" y2="1"><stop offset="0" stop-color="#7b92f2" stop-opacity=".17"/><stop offset="1" stop-color="#7b92f2" stop-opacity="0"/></linearGradient></defs>${[0,1,2,3].map(i=>{let yy=T+i*(H-T-B)/3,v=Math.round(max-i*(max-min)/3);return `<line class="chart-grid" x1="${L}" y1="${yy}" x2="${W-R}" y2="${yy}"/><text class="chart-label" x="0" y="${yy+3}">${v>=1000?(v/1000).toFixed(1)+'k':v}</text>`}).join('')}<path class="area" d="${path} L${x(vals.length-1)} ${H-B} L${L} ${H-B}Z"/><path class="line-hist" d="${path}"/><path class="line-forecast" d="${fpath}"/>${rows.map((r,i)=>i%2===0||i===rows.length-1?`<text class="chart-label" x="${x(i)}" y="${H-5}" text-anchor="middle">${r.month}</text>`:'').join('')}</svg>`}
function heading(title,desc,actions=''){return `<div class="page-heading"><div><div class="eyebrow">Travel intelligence / ${esc(pages[page]||page)}</div><h1>${title}</h1><p>${desc}</p></div><div class="actions">${actions}</div></div>`}
function notice(text='Synthetic booking data · Social and market signals are simulated. Forecasts are decision-support estimates, not trained TBO models.'){return `<div class="notice"><b>ⓘ &nbsp;Prototype data</b>${text}</div>`}
function badge(label){let c=label==='High potential'?'green':label==='High risk'?'red':label==='Moderate potential'||label==='Moderate'?'amber':'blue';return `<span class="badge ${c}">${esc(label)}</span>`}
function table(rows,cols){return `<div class="table-wrap"><table class="table"><thead><tr>${cols.map(c=>`<th>${c.label}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.map(r=>`<tr>${cols.map(c=>`<td class="${c.cls||''}">${c.render?c.render(r):esc(r[c.key]??'—')}</td>`).join('')}</tr>`).join(''):`<tr><td colspan="${cols.length}" class="empty">No matching data.</td></tr>`}</tbody></table></div>`}
const moneyCell=k=>r=>money(r[k]),destinationCell=r=>`<span class="dest-cell">${esc(r.destination)}<small>${esc(r.code)} · ${esc(r.region||'')}</small></span>`;

// ── OVERVIEW ──────────────────────────────────────────────────────────
function overview(){const k=data.kpis,p=plan||data.plan,top=data.opportunities.filter(x=>x.category==='hotel').sort((a,b)=>b.score-a.score).slice(0,5);
const acdiKpi=acdiData?acdiData.reduce((s,d)=>s+(d.suppressedDemand||0),0):0;
return `${heading('Make the next move with confidence','ACDI-powered demand intelligence shows real opportunity beyond what bookings alone can reveal.',`<button class="btn" data-export>⇩ &nbsp;Export snapshot</button><button class="btn primary" data-goto="planner">✧ &nbsp;Build procurement plan</button>`)}${notice()}<div class="grid kpis">${[["Historical bookings",num(k.bookings),"12-month observed baseline","▥"],["90-day ACDI forecast",num(k.forecast),"Availability-corrected demand","↗"],["Recommended investment",money(p.investment),`${money(p.remaining)} budget held back`,"⌑"],["Expected revenue",money(p.revenue),`Profit potential ${money(p.profit)}`,"$"],["Suppressed demand",num(acdiKpi),"Rooms invisible to naive baseline","⌁"]].map((x,i)=>`<div class="card kpi"><div class="kpi-label">${x[0]}<span class="kpi-icon">${x[3]}</span></div><div class="kpi-value">${x[1]}</div><div class="kpi-foot">${i===4?`<span class="positive">${x[2]}</span>`:i===2?`<span class="positive">${x[2]}</span>`:x[2]}</div></div>`).join('')}</div><div class="grid overview-grid"><section class="card"><div class="card-head"><div><h3>Demand is building steadily</h3><p>Monthly booking volume · all destinations</p></div><select id="chart-period" class="subtle-select"><option>Last 12 months</option><option>Last 6 months</option></select></div><div class="chart-wrap" id="main-chart">${chartSvg(data.historical)}</div><div class="legend"><span><i></i>Historical bookings</span><span><i class="green"></i>Illustrative trend extension</span></div></section><section class="card"><div class="card-head"><div><h3>Destination opportunities</h3><p>Ranked on ACDI score and risk</p></div><button class="btn" data-goto="opportunities">View all →</button></div><div class="ranking">${top.map((r,i)=>`<div class="rank-row"><div class="rank-n">0${i+1}</div><div><div class="rank-name">${r.destination} <span class="badge green">${r.growth>17?'Emerging':'Rising'}</span></div><div class="rank-meta">${r.categoryName} · ${r.growth}% forecast growth</div><div class="score-bar"><i style="width:${r.score}%"></i></div></div><div class="rank-score">${r.score}</div></div>`).join('')}</div></section></div><div class="grid lower-grid"><section class="card"><div class="card-head"><div><h3>Procurement at a glance</h3><p>Fox-optimized allocations · ACDI-corrected quantities</p></div><button class="btn" data-goto="planner">Adjust plan →</button></div>${table(p.purchases.slice(0,5),[{label:'Destination',render:destinationCell},{label:'Inventory',key:'categoryName'},{label:'Quantity',render:r=>num(r.recommended)},{label:'Investment',render:moneyCell('procurementCost')},{label:'Expected profit',render:r=>`<b class="positive">${money(r.profit)}</b>`}])}</section><section class="card"><div class="card-head"><div><h3>Intelligence quick-links</h3><p>Explore the new ACDI modules</p></div></div><div class="signal">${[['◉','Hidden demand intelligence','Discover demand suppressed by stockouts','hidden-demand'],['⊛','Supplier intelligence','Compare suppliers by expected net profit','suppliers'],['⌁','Risk simulator','Stress-test procurement assumptions','risk'],['✧','Recommendations','Read the full procurement rationale','recommendations']].map(([icon,title,desc,go])=>`<div class="signal-row"><span class="signal-icon">${icon}</span><div class="signal-copy"><b>${title}</b><small>${desc}</small></div><button class="btn" data-goto="${go}" style="font-size:9px;padding:5px 9px">Open →</button></div>`).join('')}</div></section></div>`}

// ── HISTORICAL ────────────────────────────────────────────────────────
function historicalPage(){const h=data.historical;return `${heading('Read the demand behind the bookings','Twelve months of ACDI-generated synthetic booking history across a balanced destination portfolio.',`<button class="btn" data-export>⇩ &nbsp;Export data</button>`)}${notice()}<div class="grid three-col" style="margin-bottom:14px">${[['Bookings',num(data.kpis.bookings),'Historical booking records'],['Look-to-book',`1:${(data.kpis.searches/data.kpis.bookings).toFixed(1)}`,'Searches per booking'],['Sold-out signals',num(data.kpis.soldOut),'Days with zero available inventory']].map(x=>`<div class="card panel"><p>${x[2]}</p><div class="big-stat" style="margin-top:8px">${x[1]}</div><p style="margin-top:5px">${x[0]}</p></div>`).join('')}</div><div class="grid overview-grid"><section class="card"><div class="card-head"><div><h3>Bookings and search activity</h3><p>Monthly series · searches driven by Poisson arrival process simulation</p></div></div><div class="chart-wrap">${chartSvg(h)}</div></section><section class="card"><div class="card-head"><div><h3>How this data is generated</h3><p>3-layer ACDI synthetic harness</p></div></div><div class="signal"><div class="signal-row"><span class="signal-icon">1</span><div class="signal-copy"><b>Layer 1 — Sealed ground truth</b><small>Latent demand via log-normal distribution with exogenous shocks. Estimator has zero access.</small></div></div><div class="signal-row"><span class="signal-icon">2</span><div class="signal-copy"><b>Layer 2 — Observable simulation</b><small>Poisson arrivals deplete daily supply. Sold-out arrivals generate frustrated searches independently.</small></div></div><div class="signal-row"><span class="signal-icon">3</span><div class="signal-copy"><b>Layer 3 — ACDI estimation</b><small>Uses A_time (time-based availability) to detruncate observed bookings. No ground-truth access.</small></div></div></div></section></div><section class="card" style="margin-top:14px"><div class="card-head"><div><h3>Monthly booking history</h3><p>Aggregated across all destinations · ACDI synthetic harness</p></div></div>${table(h,[{label:'Month',key:'month'},{label:'Bookings',render:r=>num(r.bookings)},{label:'Searches',render:r=>num(r.searches)},{label:'Look-to-book',render:r=>`1:${(r.searches/r.bookings).toFixed(1)}`},{label:'Cancellations',render:r=>num(r.cancellations)},{label:'Sold-out signals',key:'soldOut'}])}</section>`}

// ── SOCIAL ────────────────────────────────────────────────────────────
function socialPage(){let s=data.social.slice().sort((a,b)=>b.mentions-a.mentions);return `${heading('See where conversations are gathering','Social attention can surface emerging interest. It is a supporting signal, never confirmed booking intent.')}${notice('Social mentions and sentiment are simulated sample signals. No live Reddit, YouTube or X connection is configured.')}<div class="grid overview-grid"><section class="card"><div class="card-head"><div><h3>Destination attention index</h3><p>Illustrative relative mentions and recent growth</p></div></div><div class="ranking">${s.map((x,i)=>`<div class="rank-row"><div class="rank-n">0${i+1}</div><div><div class="rank-name">${x.destination}</div><div class="rank-meta">${x.label} · sentiment ${(x.sentiment*100).toFixed(0)}%</div><div class="progress"><i style="width:${x.mentions}%"></i></div></div><div class="rank-score">+${x.change}%</div></div>`).join('')}</div></section><section class="card panel"><h3>Signal hygiene</h3><p style="margin:7px 0 15px;line-height:1.65">Social lift is bounded at ±3% to prevent viral spikes dominating procurement decisions. It contributes to the opportunity score but not to the ACDI demand estimate.</p><div class="signal-row"><span class="signal-icon">✓</span><div class="signal-copy"><b>Bounded social lift</b><small>Social lift is capped to prevent viral spikes dominating demand.</small></div></div><div class="signal-row"><span class="signal-icon">!</span><div class="signal-copy"><b>Not purchase intent</b><small>Validate attention against ACDI demand and supplier availability.</small></div></div></section></div><section class="card" style="margin-top:14px"><div class="card-head"><div><h3>Trend radar</h3><p>Destinations with stronger emerging attention</p></div></div>${table(s,[{label:'Destination',render:r=>`<span class="dest-cell">${r.destination}<small>Sample mention index</small></span>`},{label:'Attention index',render:r=>num(r.mentions)},{label:'Growth',render:r=>`<span class="positive">+${r.change}%</span>`},{label:'Sentiment proxy',render:r=>`${Math.round(r.sentiment*100)}%`},{label:'Signal status',render:r=>'<span class="badge blue">Simulated</span>'}])}</section>`}

// ── MARKET ────────────────────────────────────────────────────────────
function marketPage(){return `${heading('Context that can shift the curve','Upcoming seasonal and cultural demand windows are modeled as scenarios for planning.',`<button class="btn" data-goto="risk">Explore scenarios →</button>`)}${notice('Events and impact estimates are simulated scenario signals, not a verified live event or disruption feed.')}<div class="grid two-col"><section class="card"><div class="card-head"><div><h3>Upcoming demand windows</h3><p>Potential impact is illustrative and should be validated</p></div></div><div class="panel">${data.events.map(e=>`<div class="event-row"><div class="event-date">${e.date}</div><div><div class="event-name">${e.destination} · ${e.event}</div><div class="event-desc">${e.type} signal · ${e.status}</div></div><div class="event-impact">${e.impact}</div></div>`).join('')}</div></section><section class="card panel"><h3>Market signal coverage</h3><p style="margin:6px 0 14px">Operational sources are not connected. Scenario values are exposed to the forecast and risk controls so impact can be explored without implying current market data.</p>${[['Seasonality','Scenario curve','78%'],['Events','Sample calendar','62%'],['Flight connectivity','Not connected','—'],['Weather','Not connected','—'],['FX and supplier pricing','Adjustable scenario','31%']].map(x=>`<div style="padding:11px 0;border-bottom:1px solid #edf0f3;display:flex;justify-content:space-between;align-items:center"><div><b style="font-size:10px">${x[0]}</b><div class="control-help">${x[1]}</div></div><span class="badge ${x[2]==='—'?'amber':'green'}">${x[2]}</span></div>`).join('')}</section></div>`}

// ── FORECAST ──────────────────────────────────────────────────────────
function forecastPage(){const op=data.opportunities.filter(x=>x.category==='hotel');return `${heading('Project demand with ACDI corrections','Availability-corrected demand estimates reveal hidden booking potential beyond the naive baseline.')}${notice('Confidence bands are log-normal 10th–90th percentile ranges, not validated statistical intervals.')}<div class="grid overview-grid"><section class="card"><div class="card-head"><div><h3>Bookings with 90-day trend</h3><p>Historical monthly series and trend extension</p></div></div><div class="chart-wrap">${chartSvg(data.historical)}</div><div class="legend"><span><i></i>Historical demand</span><span><i class="green"></i>Trend extension</span></div></section><section class="card panel"><h3>ACDI vs Naive comparison</h3><p style="margin:6px 0 12px">ACDI detruncates observed bookings using time-based availability to recover suppressed demand.</p><div class="signal-row"><span class="signal-icon">▥</span><div class="signal-copy"><b>Naive baseline</b><small>Observed bookings × growth multiplier (ignores stockouts)</small></div></div><div class="signal-row"><span class="signal-icon">◉</span><div class="signal-copy"><b>ACDI estimate</b><small>D_hat = B_obs / A_time + search-side frustration correction</small></div></div><div class="signal-row"><span class="signal-icon">↗</span><div class="signal-copy"><b>Suppressed demand</b><small>Rooms invisible to naive systems during stockout periods</small></div></div><div class="notice" style="margin-top:13px">No trained model or accuracy score is claimed. MAPE validation is available on the <button class="btn" data-goto="hidden-demand" style="font-size:9px;padding:4px 8px">Hidden Demand</button> page.</div></section></div><section class="card" style="margin-top:14px"><div class="card-head"><div><h3>Forecast by destination · ACDI corrected</h3><p>Base estimate and log-normal 10th–90th percentile planning range</p></div><div class="filters"><select id="forecast-cat"><option value="hotel">Hotels</option><option value="flight">Flights</option></select></div></div><div id="forecast-table">${forecastTable(op)}</div></section>`}
function forecastTable(rows){return table(rows,[{label:'Destination',render:destinationCell},{label:'Monthly baseline',render:r=>num(r.historical)},{label:'ACDI 90-day',render:r=>`<b>${num(r.forecast)}</b>`},{label:'Naive 90-day',render:r=>`<span style="color:#8096a0">${num(r.naiveForecast)}</span>`},{label:'Suppressed',render:r=>`<span class="${r.suppressedDemand>0?'positive':''}">+${num(r.suppressedDemand)}</span>`},{label:'Planning range',render:r=>`${num(Math.round(r.forecast*.79))} – ${num(Math.round(r.forecast*1.28))}`},{label:'Growth',render:r=>`<span class="positive">+${r.growth}%</span>`}])}

// ── OPPORTUNITIES ─────────────────────────────────────────────────────
function explorer(){const dest=oppFilter.destination,cat=oppFilter.category;let rows=data.opportunities.filter(x=>(dest==='all'||x.code===dest)&&(cat==='all'||x.category===cat));return `${heading('Find the inventory worth pursuing','ACDI-corrected demand, Fox-optimal quantities, and best-supplier economics.',`<button class="btn" data-goto="planner">Open procurement planner →</button>`)}${notice()}<section class="card"><div class="card-head"><div><h3>Ranked procurement opportunities</h3><p>Expected values use closed-form E[min(Q,D)] — no deterministic shortcut</p></div><div class="filters"><select id="opp-destination"><option value="all">All destinations</option>${data.destinations.map(d=>`<option value="${d.id}" ${dest===d.id?'selected':''}>${d.name}</option>`).join('')}</select><select id="opp-category"><option value="all" ${cat==='all'?'selected':''}>All inventory</option><option value="hotel" ${cat==='hotel'?'selected':''}>Hotels</option><option value="flight" ${cat==='flight'?'selected':''}>Flights</option></select></div></div><div id="opp-table">${opportunityTable(rows)}</div></section>`}
function opportunityTable(rows){return table(rows,[{label:'Destination',render:destinationCell},{label:'Category',key:'categoryName'},{label:'ACDI Forecast',render:r=>`<b>${num(r.forecast)}</b>`},{label:'Naive',render:r=>`<span style="color:#8096a0">${num(r.naiveForecast)}</span>`},{label:'Suppressed',render:r=>`<span class="${r.suppressedDemand>0?'positive':''}">+${num(r.suppressedDemand||0)}</span>`},{label:'Buy cost',render:moneyCell('cost')},{label:'Sell price',render:moneyCell('sell')},{label:'Margin',render:r=>`<span class="${r.margin>0?'positive':'negative'}">${money(r.margin)}</span>`},{label:'Q*',render:r=>num(r.recommended)},{label:'Score',render:r=>`<b>${r.score}</b>`},{label:'Read',render:r=>badge(r.label)}])}

// ── PLANNER (upgraded) ────────────────────────────────────────────────
function planner(){const p=plan||data.plan;
const acdiSummary=acdiData?acdiData.reduce((acc,d)=>({total:acc.total+d.acdiMu90,naive:acc.naive+d.naiveMu90,suppressed:acc.suppressed+(d.suppressedDemand||0)}),{total:0,naive:0,suppressed:0}):{total:0,naive:0,suppressed:0};
return `${heading('Plan procurement around the opportunity','Fox marginal allocation (Δi/vi) · ACDI-corrected newsvendor quantities · downside risk aversion γ.')}${notice('Expected profit uses closed-form log-normal E[min(Q,D)]. Not CVaR. Fox allocation provably optimal for separable concave under single budget constraint.')}<div class="acdi-strip"><div class="acdi-stat"><label>ACDI total 90-day demand</label><div class="val">${num(acdiSummary.total)}</div><div class="sub">vs naive ${num(acdiSummary.naive)}</div></div><div class="acdi-stat"><label>Suppressed demand recovered</label><div class="val">+${num(acdiSummary.suppressed)}</div><div class="sub">rooms invisible to naive baseline</div></div><div class="acdi-stat"><label>Fox optimizer mode</label><div class="val" id="optimizer-mode-label">${(plan||data.plan).assumptions?.gamma>0?'Risk-penalized':'Expected profit'}</div><div class="sub">Δi/vi marginal efficiency</div></div></div><div class="grid planner-layout"><section class="card control-card"><h3 style="margin:0">Planning assumptions</h3><p style="font-size:10px;color:#8b98a5;margin:5px 0">Changes recalculate the recommendation.</p><div class="control-group"><label>Available budget <b id="budget-label">${money(p.budget)}</b></label><input id="budget" type="range" min="25000" max="1000000" step="25000" value="${Math.min(p.budget,1000000)}"><div class="control-help">Adjust your total procurement envelope</div></div><div class="control-group"><label>Risk tolerance <b id="risk-label">55 / 100</b></label><input id="risk-tolerance" type="range" min="0" max="100" value="55"><div class="control-help">Higher tolerance permits higher risk rows.</div></div><div class="control-group"><label>Overage aversion γ <span class="gamma-label" id="gamma-label">γ=0.0</span></label><input id="gamma-slider" type="range" min="0" max="5" step="0.5" value="0"><div class="control-help">0 = pure expected profit · higher γ penalises unsold inventory risk. Not CVaR.</div></div><div class="control-group"><label>Minimum expected margin</label><input id="min-margin" type="number" min="0" max="100" step="1" value="0"><div class="control-help">Unit contribution as a percent of buy cost</div></div><div class="control-group"><label>Destination scope</label><select id="planner-destination"><option value="all">All destinations</option>${data.destinations.map(d=>`<option value="${d.id}">${d.name}</option>`).join('')}</select></div><div class="control-group"><label>Inventory</label><select id="planner-category"><option value="all">Hotels and flights</option><option value="hotel">Hotels</option><option value="flight">Flights</option></select></div><button class="btn primary" id="recalculate" style="width:100%">Recalculate plan &nbsp;→</button><p class="control-help" style="line-height:1.5">The optimizer can retain unused budget when no eligible opportunities remain.</p><div style="margin-top:16px;border-top:1px solid #edf0f3;padding-top:13px"><button class="btn" data-goto="hidden-demand" style="width:100%;margin-bottom:7px">◉ View hidden demand analysis →</button><button class="btn" data-goto="suppliers" style="width:100%">⊛ View supplier intelligence →</button></div></section><section><div class="grid result-grid">${[['Initial budget','budget'],['Recommended investment','investment'],['Expected revenue','revenue'],['Expected profit','profit']].map(([l,k])=>`<div class="card result-stat"><label>${l}</label><div id="stat-${k}">${money(p[k])}</div></div>`).join('')}</div><div class="card" style="margin-bottom:13px"><div class="card-head"><div><h3>Allocation &amp; retained capital</h3><p id="allocation-caption">${money(p.investment)} allocated · ${money(p.remaining)} retained · ${p.roi}% expected return on invested capital</p></div><span class="badge green">Fox optimal</span></div><div class="panel"><div class="allocation" id="allocation-bar">${allocation(p)}</div><div class="legend"><span><i></i>Hotels</span><span><i style="background:#6685ed"></i>Flights</span><span><i style="background:#edaa56"></i>Retained budget</span></div></div></div><div class="card"><div class="card-head"><div><h3>Recommended purchases</h3><p id="purchase-count">${p.purchases.length} procurement line items · Fox Δi/vi allocation</p></div></div><div id="plan-purchases">${purchaseTable(p)}</div></div><div class="card" style="margin-top:13px"><div class="card-head"><div><h3>Procurement timing urgency</h3><p>PDUI heuristic · 45 days to travel date assumed</p></div></div><div id="timing-panel" style="padding:0 16px 10px">${renderTimingPanel()}</div></div></section></div>`}
function renderTimingPanel(){if(!timingData)return '<div class="loading">Loading timing data…</div>';return timingData.slice(0,8).map(t=>`<div class="timing-row"><div class="timing-dest">${esc(t.destName)}</div><div class="timing-pace">Pace ${(t.observedPaceFraction*100).toFixed(0)}% · expected ${(t.expectedPaceFraction*100).toFixed(0)}%</div><div class="timing-price">$${t.supplierPriceNow} (+${t.priceEscalationPct}%)</div><span class="badge ${t.urgencyScore>=70?'urgent':t.urgencyScore>=40?'watch':'defer'}">${esc(t.urgencyLabel.split(' ')[0])}</span></div>`).join('')}
function allocation(p){const total=p.budget||1,h=p.purchases.filter(x=>x.category==='hotel').reduce((s,x)=>s+x.procurementCost,0),f=p.purchases.filter(x=>x.category==='flight').reduce((s,x)=>s+x.procurementCost,0);return [[h,'#12a889'],[f,'#6685ed'],[p.remaining,'#edaa56']].filter(x=>x[0]>0).map(x=>`<span style="width:${x[0]/total*100}%;background:${x[1]}"></span>`).join('')}
function purchaseTable(p){return table(p.purchases,[{label:'Destination',render:destinationCell},{label:'Inventory',key:'categoryName'},{label:'Q* (Fox)',render:r=>`${num(r.recommended)} / ${num(r.available)}`},{label:'Investment',render:moneyCell('procurementCost')},{label:'E[revenue]',render:moneyCell('revenue')},{label:'E[profit]',render:r=>`<b class="${r.profit>=0?'positive':'negative'}">${money(r.profit)}</b>`},{label:'Overage risk',render:moneyCell('riskExposure')},{label:'Supplier',render:r=>`<span style="font-size:9px">${esc(r.chosenSupplierName||'—')}</span>`}])}

// ── RISK SIMULATOR ────────────────────────────────────────────────────
function riskPage(){const p=plan||data.plan;return `${heading('Stress test the recommendation','Explore how demand, cancellation and supplier-cost changes alter quantities and portfolio exposure.')}${notice()}<div class="grid planner-layout"><section class="card control-card"><h3 style="margin:0">Market scenario</h3><div class="control-group"><label>Demand change <b id="demand-label">0%</b></label><input id="demand-shift" type="range" min="-30" max="40" value="0"></div><div class="control-group"><label>Supplier price change <b id="supplier-label">0%</b></label><input id="supplier-shift" type="range" min="0" max="30" value="0"></div><div class="control-group"><label>Cancellation rate change <b id="cancel-label">0 pts</b></label><input id="cancel-shift" type="range" min="0" max="20" value="0"></div><div class="control-group"><label>Budget adjustment <b id="scenario-budget-label">${money(p.budget)}</b></label><input id="scenario-budget" type="range" min="25000" max="1000000" step="25000" value="${Math.min(p.budget,1000000)}"></div><button class="btn primary" id="run-scenario" style="width:100%">Run scenario &nbsp;→</button></section><section><div class="grid result-grid">${[['Investment','investment'],['Expected revenue','revenue'],['Expected profit','profit'],['Overage risk','riskExposure']].map(([l,k])=>`<div class="card result-stat"><label>${l}</label><div id="risk-${k}">${money(p[k])}</div></div>`).join('')}</div><div class="card"><div class="card-head"><div><h3>Scenario impact</h3><p id="scenario-note">Baseline scenario with the current planner recommendations</p></div></div><div class="panel"><div class="grid two-col">${[['Recommended units','scenario-units'],['Budget retained','scenario-remaining'],['ROI on investment','scenario-roi'],['Demand shock','scenario-demand']].map(([l,id])=>`<div style="padding:12px;background:#f8fafb;border-radius:6px"><div class="control-help">${l}</div><b id="${id}" style="display:block;margin-top:5px">—</b></div>`).join('')}</div></div></div><div class="card" style="margin-top:13px"><div class="card-head"><div><h3>Scenario allocation</h3><p>Fox optimizer recalculates when assumptions change</p></div></div><div id="risk-purchases">${purchaseTable(p)}</div></div></section></div>`}

// ── RECOMMENDATIONS ───────────────────────────────────────────────────
function recommendationPage(){const p=plan||data.plan;return `${heading('A clear case for each purchase','Each line ties its quantity and financial view to ACDI demand, supplier economics and supply.')}${notice()}<div class="grid three-col" style="margin-bottom:14px">${[['Expected profit',money(p.profit)],['Investment',money(p.investment)],['Retained budget',money(p.remaining)]].map(x=>`<div class="card panel"><p>${x[0]}</p><div class="big-stat" style="margin-top:8px">${x[1]}</div></div>`).join('')}</div><section class="card"><div class="card-head"><div><h3>Procurement rationale</h3><p>ACDI-corrected quantities · Fox Δi/vi allocation · closed-form E[min(Q,D)]</p></div><button class="btn primary" data-goto="planner">Edit assumptions →</button></div><div id="recommendation-list">${p.purchases.length?p.purchases.slice(0,8).map((r,i)=>`<div class="panel" style="border-bottom:1px solid #edf0f3;display:grid;grid-template-columns:32px 1fr auto;gap:9px;align-items:start"><span class="kpi-icon">0${i+1}</span><div><h3>${r.destination} · ${r.categoryName} · ${num(r.recommended)} units (Q*)</h3><p style="margin-top:6px;line-height:1.6">${esc(r.explanation)}</p><p style="margin-top:6px">Supplier: ${esc(r.chosenSupplierName||'—')} · Expected revenue ${money(r.revenue)}, expected profit ${money(r.profit)}, overage risk ${money(r.riskExposure)}.</p><p style="margin-top:6px;color:#8a9bac;font-size:10px">What could change it: lower ACDI demand, higher phantom rate, stricter budget, or higher γ aversion.</p></div><div>${badge(r.label)}</div></div>`).join(''):`<div class="empty">No purchase meets current financial and risk constraints. Retain the budget or loosen the planning assumptions.</div>`}</div></section><div class="card panel" style="margin-top:14px"><h3>Engine method</h3><p style="margin-top:7px;line-height:1.65">${esc(p.model)}</p></div>`}

// ── HIDDEN DEMAND INTELLIGENCE (new M11) ─────────────────────────────
function hiddenDemandPage(){
  if(!acdiData){return `<div class="loading">Loading ACDI data… <span>•••</span></div>`}
  const totalSuppressed=acdiData.reduce((s,d)=>s+(d.suppressedDemand||0),0);
  const totalLostRevenue=acdiData.reduce((s,d)=>s+(d.lostRevenue||0),0);
  const maxACDI=Math.max(...acdiData.map(d=>d.acdiMu90||0));
  const valReport=validateData;

  return `${heading('Discover demand suppressed by inventory shortages','ACDI identifies booking opportunities invisible to naive systems — demand that existed but could not be fulfilled.',`<button class="btn" data-goto="planner">Open planner →</button>`)}${notice('Demand suppression estimates use time-based availability A_time and frustrated search signals. Ground-truth validation uses sealed synthetic Layer 1 data.')}<div class="grid hd-layout"><section class="card"><div class="hd-summary"><h3>Portfolio suppressed demand</h3><div class="hd-kpi-row"><div class="hd-kpi"><label>Total suppressed demand</label><div class="val">+${num(totalSuppressed)}</div><div class="sub">rooms ACDI recovered vs naive</div></div><div class="hd-kpi"><label>Est. lost revenue</label><div class="val">${money(totalLostRevenue)}</div><div class="sub">if suppressed demand had been procured</div></div></div><h3 style="margin-top:4px">Shortage intensity σ-score</h3><div class="demand-compare">${acdiData.map(d=>{const sig=d.sigmaScore||0;const level=sig>60?'high':sig>30?'med':'low';return `<div class="gap-row" style="grid-template-columns:90px 1fr 60px 50px"><div style="font-size:9px;font-weight:600;color:#374f61">${esc(d.destName||d.destId)}</div><div class="gap-heat"><div class="gap-heat-fill" style="width:${Math.min(100,sig)}%;background:${sig>60?'#e87373':sig>30?'#edaa56':'#18ad8c'}"></div></div><div style="font-size:9px;font-weight:700;color:#364957">${sig}</div><span class="sigma-badge ${level}">${level.toUpperCase()}</span></div>`}).join('')}</div></div></section><section class="card"><div class="card-head"><div><h3>ACDI vs Naive demand by destination</h3><p>90-day planning horizon · hotel rooms</p></div></div><div style="padding:14px 16px"><div style="display:flex;gap:14px;margin-bottom:12px;font-size:9px;color:#7b8a98"><span><i style="display:inline-block;width:9px;height:9px;border-radius:2px;background:#18ad8c;margin-right:4px"></i>ACDI corrected</span><span><i style="display:inline-block;width:9px;height:9px;border-radius:2px;background:#8096f1;margin-right:4px"></i>Naive baseline</span><span><i style="display:inline-block;width:9px;height:9px;border-radius:2px;background:#edaa56;opacity:.8;margin-right:4px"></i>Suppressed</span></div><div class="demand-compare">${acdiData.map(d=>{const acdi=d.acdiMu90||0,naive=d.naiveMu90||0,supp=Math.max(0,d.suppressedDemand||0),pct=Math.round((supp/Math.max(1,naive))*100);return `<div class="demand-row"><div class="demand-row-label" title="${d.destName||d.destId}">${esc((d.destName||d.destId).substring(0,10))}</div><div class="demand-bars"><div class="demand-bar-wrap"><div class="demand-bar acdi-bar" style="width:${Math.round(acdi/maxACDI*100)}%"></div></div><div class="demand-bar-wrap"><div class="demand-bar naive-bar" style="width:${Math.round(naive/maxACDI*100)}%"></div></div></div><div class="demand-value">${num(acdi)}</div></div>`}).join('')}</div></div></section></div><section class="card" style="margin-top:14px"><div class="card-head"><div><h3>Opportunity gap table</h3><p>Suppressed demand quantified · estimated lost revenue if capacity had been available</p></div></div>${table(acdiData,[{label:'Destination',render:r=>`<b style="font-size:10px">${esc(r.destName||r.destId)}</b>`},{label:'ACDI 90-day',render:r=>`<b>${num(r.acdiMu90||0)}</b>`},{label:'Naive 90-day',render:r=>`<span style="color:#8096a0">${num(r.naiveMu90||0)}</span>`},{label:'Suppressed demand',render:r=>`<span class="${(r.suppressedDemand||0)>0?'positive':''}">+${num(r.suppressedDemand||0)}</span>`},{label:'Uplift',render:r=>`<span class="positive">${r.upliftPct||0}%</span>`},{label:'Est. lost revenue',render:r=>`<span class="positive">${money(r.lostRevenue||0)}</span>`},{label:'Avg A_time',render:r=>`${Math.round((r.avgATime||0)*100)}%`}])}</section>${valReport?`<section class="card" style="margin-top:14px"><div class="card-head"><div><h3>Blind MAPE validation against sealed ground truth</h3><p>Estimator had zero access to Layer 1 during estimation. Evaluation is post-hoc only.</p></div></div><div style="padding:14px 16px"><div style="display:flex;gap:20px;padding:13px;background:#eaf7f3;border-radius:7px;margin-bottom:14px"><div style="flex:1"><div style="font-size:9px;color:#3a7a63;font-weight:600;text-transform:uppercase">ACDI avg MAPE</div><div style="font:700 20px Manrope;color:#0d7a62;margin-top:4px">${valReport.aggregate.avgACDImape}%</div></div><div style="flex:1"><div style="font-size:9px;color:#7a6a3a;font-weight:600;text-transform:uppercase">Naive avg MAPE</div><div style="font:700 20px Manrope;color:#997020;margin-top:4px">${valReport.aggregate.avgNaiveMAPE}%</div></div><div style="flex:1"><div style="font-size:9px;color:#1f4a3a;font-weight:600;text-transform:uppercase">Improvement</div><div style="font:700 20px Manrope;color:#0a9879;margin-top:4px">-${valReport.aggregate.improvement}pp</div></div></div><div>${valReport.destinations.map(d=>`<div class="validate-row"><div class="validate-dest">${esc(d.destName)}</div><div class="mape-pair"><div style="font-size:8px;color:#3a7a63;margin-bottom:2px">ACDI ${d.acdiMAPE}%</div><div class="mape-meter" style="margin:0"><div class="mape-bar-wrap"><div class="mape-bar acdi" style="width:${Math.min(100,d.acdiMAPE*4)}%"></div></div></div></div><div class="mape-pair"><div style="font-size:8px;color:#9b7320;margin-bottom:2px">Naive ${d.naiveMAPE}%</div><div class="mape-meter" style="margin:0"><div class="mape-bar-wrap"><div class="mape-bar naive" style="width:${Math.min(100,d.naiveMAPE*4)}%"></div></div></div></div></div>`).join('')}</div><div class="notice" style="margin-top:12px"><b>ⓘ</b> ${esc(valReport.disclaimer)}</div></div></section>`:''}`}

// ── SUPPLIER INTELLIGENCE (new M12) ───────────────────────────────────
function suppliersPage(){
  if(!suppliersData){return `<div class="loading">Loading supplier data… <span>•••</span></div>`}
  const dest=suppliersData.find(d=>d.destId===activeSupTab)||suppliersData[0];
  if(!dest)return '';
  return `${heading('Compare suppliers by expected net profit','Effective cost, phantom rejection rates, and newsvendor-optimal quantities across all partners.',`<button class="btn" data-goto="planner">Use in procurement plan →</button>`)}${notice('Supplier data is synthetic. Effective cost = v / (1 − phantom). E[Π(Q,s)] uses the validated single-deduction profit formula — no double-counting of procurement cost.')}<div class="sup-dest-tabs">${suppliersData.map(d=>`<button class="sup-tab ${d.destId===activeSupTab?'active':''}" data-sup-tab="${d.destId}">${esc(d.destName)}</button>`).join('')}</div><div class="card" style="border-top-left-radius:0;border-top-right-radius:0"><div class="card-head"><div><h3>${esc(dest.destName)} — Supplier comparison</h3><p>ACDI 90-day demand: ${num(dest.acdiMu90)} rooms · Best by E[Π]: ${esc(dest.bestSupplierId||'—')}</p></div></div><div class="supplier-grid">${dest.suppliers.map(s=>{const isBest=s.id===dest.bestSupplierId;return `<div class="supplier-card ${isBest?'best':''}"><h4>${esc(s.name)}<span style="margin-left:7px;font-size:9px;color:#8a97a4;font-weight:400">${s.id}</span>${isBest?`<span class="best-tag badge green">✓ Best</span>`:''}</h4><div style="display:grid;grid-template-columns:1fr 1fr;gap:7px;font-size:9px;color:#647386"><div><span style="color:#8a97a4">List price:</span> <b>$${s.v}</b></div><div><span style="color:#8a97a4">Eff. cost:</span> <b class="${s.effectiveCost>s.v?'worse':'better'}">$${s.effectiveCost}</b></div><div><span style="color:#8a97a4">Salvage:</span> <b>${Math.round(s.salvage*100)}%</b></div><div><span style="color:#8a97a4">Reliability:</span> <b>${Math.round(s.reliability*100)}%</b></div></div><div style="margin:9px 0 4px;font-size:8px;color:#9aa5b2">Phantom rejection rate — ${Math.round(s.phantom*100)}%</div><div class="phantom-bar"><div class="phantom-fill" style="width:${Math.round(s.phantom*100)*4}%"></div></div><div class="supplier-stat-row"><div class="supplier-stat"><div class="supplier-stat-label">CR (critical ratio)</div><div class="supplier-stat-val">${s.criticalRatio}</div></div><div class="supplier-stat"><div class="supplier-stat-label">Q* (90-day)</div><div class="supplier-stat-val">${num(s.optimalQ)}</div></div><div class="supplier-stat"><div class="supplier-stat-label">E[Π] 90-day</div><div class="supplier-stat-val ${s.expectedProfit>0?'better':'worse'}">${money(s.expectedProfit)}</div></div></div>${s.minCommit>0?`<div style="margin-top:9px;padding:6px 9px;background:#fffaed;border:1px solid #f0dba5;border-radius:4px;font-size:9px;color:#9b7320">⚠ Min. commitment: ${s.minCommit} rooms. DP fallback used if budget constraint binds.</div>`:''}</div>`}).join('')}</div></div><section class="card" style="margin-top:14px"><div class="card-head"><div><h3>Profit formula reference (no double-deduction)</h3><p>E[Π(Q,s)] = (1−k)(p − v_s·r_s)·E[min(Q,D)] − Q·(v_eff·(1−r_s) + p·f)</p></div></div><div class="panel" style="font-size:10px;color:#647386;line-height:1.75">v_eff = v / (1 − phantom) · Procurement cost appears exactly once. · Salvage applies to unsold and cancelled units proportionally. · CR = (v_eff(1−r)+pf) / ((1−k)(p−v·r)). · Q* = exp(ν + τ·Φ⁻¹(1−CR)) where τ = √ln(1+CV²), ν = ln(μ)−τ²/2.</div></section>`}

// ── RENDER DISPATCH ───────────────────────────────────────────────────
function demoPage(){
  if(!demoData){return `<div class="loading">Loading demo scenario… <span>•••</span></div>`}
  const d=demoData, event=d.event||{}, acdi=d.acdi||{}, gap=d.gap||{}, timing=d.timing||{}, sp=d.songkranPlan||{}, bp=d.basePlan||{};
  const profitLift=sp.profit&&bp.profit?Math.round(sp.profit-bp.profit):0;
  const suppList=d.suppliers||[];
  const best=suppList.reduce((a,b)=>a.expectedProfit>b.expectedProfit?a:b,suppList[0]||{});
  return `${heading('Bangkok Songkran 2027 — ACDI Demo Walkthrough','End-to-end demonstration of how ACDI, supplier selection, PDUI timing, and Fox allocation work together on a real festival scenario.',`<button class="btn primary" data-goto="planner">Open full planner →</button>`)}${notice('All data is synthetic. Songkran +22% demand is a scenario signal for demonstration purposes.')}<div class="grid three-col" style="margin-bottom:14px"><div class="card kpi"><div class="kpi-label">ACDI 90-day demand<span class="kpi-icon">◈</span></div><div class="kpi-value">${num(acdi.mu90||0)}</div><div class="kpi-foot">Naive baseline: ${num(gap.naiveMu90||0)} rooms</div></div><div class="card kpi"><div class="kpi-label">Suppressed demand<span class="kpi-icon">⌁</span></div><div class="kpi-value">+${num(gap.suppressedDemand||0)}</div><div class="kpi-foot positive">+${gap.upliftPct||0}% vs naive baseline</div></div><div class="card kpi"><div class="kpi-label">Songkran profit uplift<span class="kpi-icon">$</span></div><div class="kpi-value">${money(profitLift)}</div><div class="kpi-foot positive">vs base scenario (no Songkran lift)</div></div></div><div class="grid overview-grid"><section class="card"><div class="card-head"><div><h3>How ACDI works — step by step</h3><p>Walkthrough for judges</p></div></div><div class="signal"><div class="signal-row"><span class="signal-icon" style="background:#eaf7f3;color:#0a9879;font-weight:700">1</span><div class="signal-copy"><b>Sealed ground truth (Layer 1)</b><small>Latent demand D_true ~ LogNormal(ν, τ²) with exogenous shocks. Estimator has zero access. Used only for MAPE evaluation after the fact.</small></div></div><div class="signal-row"><span class="signal-icon" style="background:#eaf7f3;color:#0a9879;font-weight:700">2</span><div class="signal-copy"><b>Observable simulation (Layer 2)</b><small>Poisson(λ) customer arrivals per day deplete inventory. Sold-out arrivals generate Poisson(L2B) frustrated searches independently — not derived from ground truth.</small></div></div><div class="signal-row"><span class="signal-icon" style="background:#eaf7f3;color:#0a9879;font-weight:700">3</span><div class="signal-copy"><b>ACDI detruncation (Layer 3)</b><small>D̂ = B_obs / A_time + search-side frustration correction. A_time = fraction of days with available inventory — observable, not a fulfilment ratio.</small></div></div><div class="signal-row"><span class="signal-icon" style="background:#eaf7f3;color:#0a9879;font-weight:700">4</span><div class="signal-copy"><b>Newsvendor Q* (log-normal)</b><small>Q* = exp(ν + τ · Φ⁻¹(CR)) where CR = (v_eff(1−r)+pf) / ((1−k)(p−vr)). Closed-form E[min(Q,D)] — no deterministic shortcut.</small></div></div><div class="signal-row"><span class="signal-icon" style="background:#eaf7f3;color:#0a9879;font-weight:700">5</span><div class="signal-copy"><b>Fox marginal allocation (Δi/vi)</b><small>Separable concave integer program. Optimal under zero integrality gap. Selects i* = argmax Δi(Qi)/vi at each step. Downside risk mode: U_γ(Q) = E[Π] − γ·Co·E[(Q−D)⁺]. NOT CVaR.</small></div></div></div></section><section class="card"><div class="card-head"><div><h3>Bangkok supplier comparison</h3><p>E[Π(Q*,s)] using corrected single-deduction formula</p></div></div><div class="supplier-grid" style="padding:12px">${suppList.map(s=>{const isBest=s.id===best.id;return `<div class="supplier-card ${isBest?'best':''}" style="margin-bottom:8px"><h4>${esc(s.name)} ${isBest?'<span class="best-tag badge green">✓ Best E[Π]</span>':''}</h4><div style="display:grid;grid-template-columns:1fr 1fr 1fr;gap:7px;font-size:9px"><div><span style="color:#8a97a4">List $${s.v}</span></div><div><span style="color:#8a97a4">Eff. $${s.effectiveCost}</span></div><div><span style="color:#8a97a4">Phantom ${Math.round((s.phantom||0)*100)}%</span></div></div><div style="margin-top:7px;font-size:10px">Q*: <b>${num(s.optimalQ||0)}</b> · E[Π]: <b class="${s.expectedProfit>0?'positive':'negative'}">${money(s.expectedProfit||0)}</b></div></div>`}).join('')}</div></section></div><div class="grid two-col" style="margin-top:14px"><section class="card"><div class="card-head"><div><h3>Songkran scenario vs base (Bangkok hotels)</h3><p>Fox optimizer output — $150k budget, hotel only</p></div></div>${table([{label:'Metric',base:'Base scenario',songkran:'Songkran +22%'},{label:'Recommended units',base:num(bp.purchases?.[0]?.recommended||0),songkran:num(sp.purchases?.[0]?.recommended||0)},{label:'Investment',base:money(bp.investment||0),songkran:money(sp.investment||0)},{label:'Expected revenue',base:money(bp.revenue||0),songkran:money(sp.revenue||0)},{label:'Expected profit',base:money(bp.profit||0),songkran:money(sp.profit||0)},{label:'Profit uplift',base:'—',songkran:`<b class="positive">+${money(profitLift)}</b>`}],[{label:'Metric',key:'label'},{label:'Base scenario',render:r=>r.base||'—'},{label:'Songkran +22%',render:r=>r.songkran||'—'}])}</section><section class="card"><div class="card-head"><div><h3>Procurement timing (PDUI heuristic)</h3><p>42 days to Songkran · explicitly labelled as heuristic</p></div></div><div class="panel"><div style="display:flex;align-items:center;gap:11px;margin-bottom:14px"><span class="badge ${timing.urgencyScore>=70?'urgent':timing.urgencyScore>=40?'watch':'defer'}" style="font-size:11px;padding:7px 13px">${esc(timing.urgencyLabel||'—')}</span><b style="font-size:20px;font-family:Manrope">${timing.urgencyScore||0}/100</b></div>${[['Expected pace',((timing.expectedPaceFraction||0)*100).toFixed(1)+'%'],['Observed pace',((timing.observedPaceFraction||0)*100).toFixed(1)+'%'],['Pace deviation',(timing.paceDeviation||0)>0?'+'+((timing.paceDeviation||0)*100).toFixed(1)+'%':((timing.paceDeviation||0)*100).toFixed(1)+'%'],['Wholesale price now','$'+(timing.supplierPriceNow||0)],['Price escalation',+(timing.priceEscalationPct||0).toFixed(1)+'%']].map(([k,v])=>`<div style="display:flex;justify-content:space-between;padding:7px 0;border-bottom:1px solid #f1f3f5;font-size:10px"><span style="color:#7b8a98">${k}</span><b>${v}</b></div>`).join('')}<p style="font-size:9px;color:#8a9bac;margin-top:11px;line-height:1.6">${esc(timing.disclaimer||'')}</p></div></section></div><div class="card panel" style="margin-top:14px"><h3>Scenario narrative</h3><p style="margin-top:7px;line-height:1.75;font-size:11px">${esc(d.narrative||'')}</p><p style="margin-top:9px;font-size:9px;color:#8a9bac">${esc(d.disclaimer||'')}</p></div>`}

function render(){if(!data)return;$('#crumb-title').textContent=pages[page]||page;const f={overview,history:historicalPage,social:socialPage,market:marketPage,forecast:forecastPage,opportunities:explorer,planner,risk:riskPage,recommendations:recommendationPage,'hidden-demand':hiddenDemandPage,suppliers:suppliersPage,demo:demoPage};const fn=f[page];if(fn){$('#content').dataset.page=page;$('#content').innerHTML=fn()}bindPage()}
function go(p){if(!pages[p])return;page=p;document.querySelectorAll('.nav-item').forEach(x=>x.classList.toggle('active',x.dataset.page===p));render();window.scrollTo(0,0)}

// ── PLANNER RECALCULATE ───────────────────────────────────────────────
async function calc(overrides={}){try{let body={budget:Number($('#budget')?.value||plan?.budget||250000),riskTolerance:Number($('#risk-tolerance')?.value||55),minMargin:Number($('#min-margin')?.value||0),gamma:Number($('#gamma-slider')?.value||0),destination:$('#planner-destination')?.value||'all',category:$('#planner-category')?.value||'all',...overrides};plan=await api('/api/optimize',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});render();toast('Procurement recommendations updated.')}catch(e){toast(e.message)}}

// ── SCENARIO ──────────────────────────────────────────────────────────
async function scenario(){try{let body={budget:Number($('#scenario-budget').value),riskTolerance:55,minMargin:0,demandShift:Number($('#demand-shift').value)/100,supplierShift:Number($('#supplier-shift').value)/100,cancelShift:Number($('#cancel-shift').value)/100};const p=await api('/api/optimize',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});$('#risk-investment').textContent=money(p.investment);$('#risk-revenue').textContent=money(p.revenue);$('#risk-profit').textContent=money(p.profit);$('#risk-riskExposure').textContent=money(p.riskExposure);$('#scenario-units').textContent=num(p.purchases.reduce((s,x)=>s+x.recommended,0));$('#scenario-remaining').textContent=money(p.remaining);$('#scenario-roi').textContent=p.roi+'%';$('#scenario-demand').textContent=(body.demandShift>=0?'+':'')+Math.round(body.demandShift*100)+'%';$('#scenario-note').textContent=`Demand ${body.demandShift>=0?'+':''}${body.demandShift*100}% · supplier costs +${body.supplierShift*100}% · cancellation +${body.cancelShift*100} points`;$('#risk-purchases').innerHTML=purchaseTable(p);toast('Scenario recalculated.');}catch(e){toast(e.message)}}

// ── DOWNLOAD ──────────────────────────────────────────────────────────
function download(){const rows=(plan||data.plan).purchases,headers=['Destination','Category','Q*','Available','Investment USD','E[Revenue] USD','E[Profit] USD','Overage risk USD','Supplier','Explanation'];const q=s=>'"'+String(s??'').replaceAll('"','""')+'"';const csv=[headers,...rows.map(r=>[r.destination,r.categoryName,r.recommended,r.available,r.procurementCost,r.revenue,r.profit,r.riskExposure,r.chosenSupplierName||'—',r.explanation])].map(x=>x.map(q).join(',')).join('\n');let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));a.download='travelpulse-acdi-plan.csv';a.click();URL.revokeObjectURL(a.href);toast('Procurement snapshot downloaded.');}

// ── PAGE EVENT BINDING ────────────────────────────────────────────────
function bindPage(){
  document.querySelectorAll('[data-goto]').forEach(x=>x.onclick=()=>go(x.dataset.goto));
  document.querySelectorAll('[data-export]').forEach(x=>x.onclick=download);
  document.querySelectorAll('[data-sup-tab]').forEach(x=>x.onclick=()=>{activeSupTab=x.dataset.supTab;render()});
  const b=$('#recalculate');if(b)b.onclick=()=>calc();
  const budget=$('#budget');if(budget)budget.oninput=()=>$('#budget-label').textContent=money(Number(budget.value));
  const rt=$('#risk-tolerance');if(rt)rt.oninput=()=>$('#risk-label').textContent=`${rt.value} / 100`;
  const gs=$('#gamma-slider');if(gs)gs.oninput=()=>{const v=Number(gs.value);$('#gamma-label').textContent=`γ=${v.toFixed(1)}`;const ml=$('#optimizer-mode-label');if(ml)ml.textContent=v>0?'Risk-penalized':'Expected profit'};
  const sr=$('#scenario-budget');if(sr)sr.oninput=()=>$('#scenario-budget-label').textContent=money(Number(sr.value));
  for(const [id,label,unit] of [['demand-shift','demand-label','%'],['supplier-shift','supplier-label','%'],['cancel-shift','cancel-label',' pts']]){const e=$('#'+id);if(e)e.oninput=()=>$('#'+label).textContent=(id==='demand-shift'&&e.value>0?'+':'')+e.value+unit;}
  const run=$('#run-scenario');if(run)run.onclick=scenario;
  const dd=$('#opp-destination');if(dd)dd.onchange=()=>{oppFilter.destination=dd.value;render()};
  const oc=$('#opp-category');if(oc)oc.onchange=()=>{oppFilter.category=oc.value;render()};
  const fc=$('#forecast-cat');if(fc)fc.onchange=()=>{$('#forecast-table').innerHTML=forecastTable(data.opportunities.filter(x=>x.category===fc.value))};
  const cp=$('#chart-period');if(cp)cp.onchange=()=>{let h=data.historical.slice(cp.value.includes('6')?-6:0);$('#main-chart').innerHTML=chartSvg(h)};
}

// ── BOOTSTRAP ─────────────────────────────────────────────────────────
$('#nav').addEventListener('click',e=>{const b=e.target.closest('[data-page]');if(b)go(b.dataset.page)});

// Load all data in parallel
Promise.all([
  api('/api/dashboard'),
  api('/api/acdi'),
  api('/api/suppliers'),
  api('/api/timing?days=45'),
  api('/api/validate'),
  api('/api/demo')
]).then(([dash,acdi,sup,tim,val,demo])=>{
  data=dash; plan=dash.plan;
  acdiData=acdi; suppliersData=sup; timingData=tim; validateData=val; demoData=demo;
  render();
}).catch(e=>{$('#content').innerHTML=`<div class="card panel"><h3>Could not load TravelPulse data</h3><p style="margin-top:8px">${esc(e.message)}. Start the local server with npm start and refresh this page.</p></div>`});
